from pathlib import Path

MARK='SJIT_HISTORY_QUERY_FINAL_V4'
JS=r'''<script>/* SJIT_HISTORY_QUERY_FINAL_V4 */(()=>{
const state={rows:[],page:1,size:20,busy:false};
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
function active(){return $('history')?.classList.contains('active')}
function controls(){const h=$('history');if(!h)return null;const dates=[...h.querySelectorAll('input[type=date]')];const text=h.querySelector('#search')||h.querySelector('input[type=text]');const selects=[...h.querySelectorAll('select')];const result=selects.find(s=>[...s.options].some(o=>/PASS|FAIL|All Result|Tất cả kết quả/i.test(o.textContent||'')));const table=h.querySelector('table.table')||h.querySelector('table');const buttons=[...h.querySelectorAll('button')];const apply=buttons.find(b=>/조회|검색|Search|Tìm kiếm|Tra cứu/i.test((b.innerText||'').trim())&&!/Excel|CSV|초기화|Xóa|Đặt lại/i.test(b.innerText||''));return{h,dates,text,result,table,apply}}
function dates(c){return{from:c.dates[0]?.value||'0000-01-01',to:c.dates[1]?.value||'9999-12-31'}}
async function load(){const c=controls(),S=window.sb;if(!c||!S||state.busy)return;state.busy=true;try{const {from,to}=dates(c);let q=await S.from('daily_inspections').select('*').gte('inspection_date',from).lte('inspection_date',to).order('inspection_date',{ascending:false});if(q.error)throw q.error;let rows=q.data||[];const term=(c.text?.value||'').trim().toLowerCase();const rv=(c.result?.value||'').trim().toUpperCase();rows=rows.filter(r=>(!term||[r.customer,r.maker,r.part_no,r.part_name,r.material_name,r.lot_no].map(v=>String(v??'').toLowerCase()).join(' ').includes(term))&&(!rv||rv==='ALL'||rv==='전체'||rv==='TẤT CẢ'||String(r.result??'').toUpperCase()===rv));state.rows=rows;state.page=1;render(c,from,to)}catch(e){console.error('SJIT history query',e);state.rows=[];render(c,dates(c).from,dates(c).to);const msg=c.h.querySelector('.history-query-error');if(msg)msg.textContent='DB 조회 오류: '+(e?.message||e)}finally{state.busy=false}}
function render(c,from,to){if(!c?.table)return;const body=c.table.tBodies[0]||c.table.createTBody();const total=state.rows.length,pages=Math.max(1,Math.ceil(total/state.size));state.page=Math.min(state.page,pages);const start=(state.page-1)*state.size,end=Math.min(start+state.size,total);body.innerHTML=state.rows.slice(start,end).map(r=>{const inq=Number(r.in_qty??r.incoming_qty??r.input_qty??0),test=Number(r.test_qty??r.inspection_qty??0),bad=Number(r.bad_qty??r.defect_qty??0),rate=test?(bad/test*100).toFixed(2):'0.00',res=String(r.result??'PASS').toUpperCase();return `<tr><td>${esc(r.inspection_date)}</td><td>${esc(r.customer??r.maker)}</td><td>${esc(r.part_no)}</td><td>${esc(r.part_name??r.material_name)}</td><td>${esc(r.lot_no??'-')}</td><td>${inq.toLocaleString()}</td><td>${test.toLocaleString()}</td><td>${bad.toLocaleString()}</td><td>${rate}%</td><td><span class="badge ${res==='FAIL'?'fail':'pass'}">${res}</span></td><td>${esc(r.inspector??'-')}</td></tr>`}).join('')||'<tr><td colspan="11" class="empty">검색된 검사 이력이 없습니다.</td></tr>';let nav=c.h.querySelector('.history-final-v4');if(!nav){nav=document.createElement('div');nav.className='history-final-v4';c.table.parentElement.appendChild(nav)}nav.innerHTML='';const info=document.createElement('span');info.textContent=`${total?start+1:0}-${end} / ${total}건`;const pagesBox=document.createElement('span');pagesBox.style.cssText='display:inline-flex;gap:5px;align-items:center;flex-wrap:wrap';const add=(txt,p,disabled=false,act=false)=>{const b=document.createElement('button');b.type='button';b.textContent=txt;b.disabled=disabled;if(act)b.className='active';b.onclick=()=>{state.page=p;render(controls(),from,to)};pagesBox.appendChild(b)};add('‹',Math.max(1,state.page-1),state.page===1);for(let p=1;p<=pages;p++){if(p>7&&p<pages-1){if(p===8){const d=document.createElement('span');d.textContent='…';pagesBox.appendChild(d)}continue}add(String(p),p,false,p===state.page)}add('›',Math.min(pages,state.page+1),state.page===pages);const size=document.createElement('label');size.innerHTML='페이지당 <select><option value="20">20</option><option value="50">50</option><option value="100">100</option></select>건';const sel=size.querySelector('select');sel.value=String(state.size);sel.onchange=()=>{state.size=Number(sel.value)||20;state.page=1;render(controls(),from,to)};nav.append(info,pagesBox,size);nav.style.cssText='display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 2px;background:#fff;border-top:1px solid #e2e8f0';let summary=c.h.querySelector('.history-final-v4-summary');if(!summary){summary=document.createElement('div');summary.className='history-final-v4-summary';const anchor=c.h.querySelector('.month-summary')||c.h.querySelector('.history-period-tools')||c.table.parentElement;anchor.insertAdjacentElement('afterend',summary)}const lots=new Set(state.rows.map(r=>r.lot_no||r.part_no||r.inspection_date));const test=state.rows.reduce((a,r)=>a+Number(r.test_qty??r.inspection_qty??0),0),bad=state.rows.reduce((a,r)=>a+Number(r.bad_qty??r.defect_qty??0),0);summary.innerHTML=`<div>기간<br><b>${esc(from)} ~ ${esc(to)}</b></div><div>검사 LOT 수<br><b>${lots.size} LOT</b></div><div>검사 수량<br><b>${test.toLocaleString()} PCS</b></div><div>불량 수량<br><b style="color:#dc2626">${bad.toLocaleString()} PCS</b></div>`}
function bind(){const c=controls();if(!c)return;if(c.apply&&!c.apply.dataset.v4){c.apply.dataset.v4='1';c.apply.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();load()},{capture:true})}c.dates.forEach(x=>{if(!x.dataset.v4){x.dataset.v4='1';x.addEventListener('change',load)}});if(c.text&&!c.text.dataset.v4){c.text.dataset.v4='1';c.text.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();load()}})}}
function tick(){if(active()){bind();if(!document.querySelector('.history-final-v4'))load()}}document.addEventListener('click',e=>{if(e.target.closest?.('[data-page="history"]'))setTimeout(tick,300)});setInterval(()=>{if(active())bind()},500);setTimeout(tick,1000);
})();</script>'''

p=Path('daily-inspection/index.html');s=p.read_text(encoding='utf-8')
if MARK not in s:
    s=s.replace('</body></html>',JS+'</body></html>')
    p.write_text(s,encoding='utf-8')

VI_MARK='SJIT_VI_HISTORY_FINAL_V4'
VI=r'''<script>/* SJIT_VI_HISTORY_FINAL_V4 */(()=>{const f=document.getElementById('appFrame');const M={'검사 이력':'Lịch sử kiểm tra','검사 이력 조회 · Excel 일괄 업로드':'Tra cứu lịch sử kiểm tra · Tải Excel hàng loạt','Maker / Part / LOT':'Nhà cung cấp / Mã Part / Số LOT','All Result':'Tất cả kết quả','Excel 업로드':'Tải Excel','기간 조회':'Tra cứu theo thời gian','오늘':'Hôm nay','최근 7일':'7 ngày gần nhất','이번 달':'Tháng này','지난 달':'Tháng trước','조회':'Tra cứu','페이지당':'Mục mỗi trang','건':'mục','검사 LOT 수':'Số LOT kiểm tra','검사 수량':'Số lượng kiểm tra','불량 수량':'Số lượng lỗi','Date':'Ngày','Part No.':'Mã Part','Part Name':'Tên vật liệu','LOT':'Số LOT','In':'Nhập','Test':'Kiểm tra','Defect':'Lỗi','Rate(%)':'Tỷ lệ (%)','Result':'Kết quả','Inspector':'Nhân viên kiểm tra','검색된 검사 이력이 없습니다.':'Không tìm thấy lịch sử kiểm tra.','조회된 검사 이력이 없습니다.':'Không có lịch sử kiểm tra được tìm thấy.'};function go(){const d=f?.contentDocument;if(!d?.body)return;const w=d.createTreeWalker(d.body,NodeFilter.SHOW_TEXT),a=[];let n;while(n=w.nextNode()){if(n.parentElement?.tagName==='SCRIPT'||n.parentElement?.tagName==='STYLE')continue;const r=n.nodeValue.trim();if(M[r])a.push([n,r,M[r]])}a.forEach(([n,r,v])=>n.nodeValue=n.nodeValue.replace(r,v));d.documentElement.lang='vi'}f?.addEventListener('load',()=>{go();setTimeout(go,300);setTimeout(go,900)});setInterval(go,700)})();</script>'''
p=Path('daily-inspection/vi.html');s=p.read_text(encoding='utf-8')
if VI_MARK not in s:
    s=s.replace('</body>\n</html>',VI+'</body>\n</html>')
    p.write_text(s,encoding='utf-8')
